import java.util.Scanner;

public class Student
{
    String name;     // name of student
    int age;         // age of student
    double mks;      // marks obtained
    String stream;   // stream allocated

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter name: ");
        name = sc.nextLine();
        System.out.print("Enter age: ");
        age = sc.nextInt();
        System.out.print("Enter marks: ");
        mks = sc.nextDouble();
    }

    void allocation()
    {
        if (mks >= 300)
            stream = "Science and Computer";
        else if (mks >= 200)
            stream = "Commerce and Computer";
        else if (mks >= 75)
            stream = "Arts and Animation";
        else
            stream = "Try Again";
    }

    void print()
    {
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Marks: " + mks);
        System.out.println("Stream allocated: " + stream);
    }

    public static void main(String args[])
    {
        Student ob = new Student();
        ob.accept();
        ob.allocation();
        ob.print();
    }
}

Sample: mks = 250 gives stream Commerce and Computer; mks = 60 gives Try Again.

