import java.util.Scanner;

public class CharSort
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        char orig[] = new char[10];   // original array
        char a[] = new char[10];      // copy to be sorted
        System.out.println("Enter 10 characters:");
        for (int i = 0; i < 10; i++)
        {
            orig[i] = sc.next().charAt(0);
            a[i] = orig[i];
        }

        for (int i = 0; i < 9; i++)             // passes
        {
            for (int j = 0; j < 9 - i; j++)     // compare adjacent characters
            {
                if (a[j] > a[j + 1])
                {
                    char t = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = t;
                }
            }
        }

        System.out.println("Original array:");
        for (int i = 0; i < 10; i++)
            System.out.print(orig[i] + " ");
        System.out.println();
        System.out.println("Sorted array:");
        for (int i = 0; i < 10; i++)
            System.out.print(a[i] + " ");
        System.out.println();
    }
}

A copy of the input is kept in orig[] so the original order can still be displayed after a[] is sorted. Characters are compared by their Unicode values.

