public class Overload
{
    // prints the 5 x 4 pattern of row numbers
    void print()
    {
        for (int i = 1; i <= 5; i++)
        {
            for (int j = 1; j <= 4; j++)
                System.out.print(i + " ");
            System.out.println();
        }
    }

    // checks whether n is a lead number
    void print(int n)
    {
        int num = n;        // working copy
        int evenSum = 0;    // sum of even digits
        int oddSum = 0;     // sum of odd digits
        while (num > 0)
        {
            int d = num % 10;
            if (d % 2 == 0)
                evenSum += d;
            else
                oddSum += d;
            num = num / 10;
        }
        if (evenSum == oddSum)
            System.out.println(n + " is a lead number.");
        else
            System.out.println(n + " is not a lead number.");
    }

    public static void main(String args[])
    {
        Overload ob = new Overload();
        ob.print();
        ob.print(3669);
    }
}

Trace for 3669: digits 9 (odd), 6 (even), 6 (even), 3 (odd) give oddSum = 12 and evenSum = 12, so it prints "3669 is a lead number."

