import java.util.Scanner;

public class LinearSearch
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        double a[] = new double[20];   // array of 20 values
        System.out.println("Enter 20 values:");
        for (int i = 0; i < 20; i++)
            a[i] = sc.nextDouble();
        System.out.print("Enter value to search: ");
        double key = sc.nextDouble();  // value to be searched
        int pos = -1;                  // index where found
        for (int i = 0; i < 20; i++)
        {
            if (a[i] == key)
            {
                pos = i;
                break;
            }
        }
        if (pos != -1)
            System.out.println("Found at position " + (pos + 1));
        else
            System.out.println("not found");
    }
}

The position printed is the 1-based position (index + 1); printing the index is also accepted if stated.

