import java.util.Scanner;

public class DigitSum
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int a[] = new int[10];
        System.out.println("Enter 10 integers:");
        for (int i = 0; i < 10; i++)
            a[i] = sc.nextInt();
        int sum1 = 0, sum2 = 0;        // sums of one digit and two digit numbers
        String s1 = "", s2 = "";       // terms shown in the output
        for (int i = 0; i < 10; i++)
        {
            if (a[i] >= 0 && a[i] <= 9)
            {
                sum1 += a[i];
                s1 = s1 + (s1.equals("") ? "" : " + ") + a[i];
            }
            else if (a[i] >= 10 && a[i] <= 99)
            {
                sum2 += a[i];
                s2 = s2 + (s2.equals("") ? "" : " + ") + a[i];
            }
        }
        System.out.println("Sum of one digit numbers : " + s1 + " = " + sum1);
        System.out.println("Sum of two digit numbers : " + s2 + " = " + sum2);
    }
}

Trace on the sample: one digit numbers 2, 4, 9, 3, 1 give 19; two digit numbers 12, 18, 25, 32, 20 give 107. The program prints:
Sum of one digit numbers : 2 + 4 + 9 + 3 + 1 = 19
Sum of two digit numbers : 12 + 18 + 25 + 32 + 20 = 107
